-- MAT-FUNC-011/012/021/053: client projects, annual budgets, central calendar and cost centres.

create table public.client_sites(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict,
 code text not null check(code~'^[A-Z][A-Z0-9_-]{1,39}$'), status text not null default 'ACTIVE' check(status in('ACTIVE','INACTIVE','ARCHIVED')),
 current_version integer not null default 1 check(current_version>0), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(), row_version integer not null default 1 check(row_version>0), unique(organization_id,code), unique(id,organization_id)
);
create table public.client_site_versions(
 id uuid primary key default extensions.gen_random_uuid(), site_id uuid not null references public.client_sites(id) on delete restrict, organization_id uuid not null,
 version integer not null check(version>0), name_fr text not null check(length(btrim(name_fr))between 2 and 160), name_ar text not null check(length(btrim(name_ar))between 2 and 160),
 address_snapshot jsonb not null check(jsonb_typeof(address_snapshot)='object'), change_reason text not null check(length(btrim(change_reason))between 3 and 500),
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(site_id,version), foreign key(site_id,organization_id)references public.client_sites(id,organization_id)on delete restrict
);

create table public.client_projects(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict,
 project_code text not null check(project_code~'^[A-Z][A-Z0-9_-]{1,39}$'), site_id uuid, status text not null default 'DRAFT' check(status in('DRAFT','PLANNED','ACTIVE','ON_HOLD','COMPLETED','CANCELLED','ARCHIVED')),
 current_version integer not null default 1 check(current_version>0), progress_basis_points integer not null default 0 check(progress_basis_points between 0 and 10000),
 started_on date, target_end_on date, completed_at timestamptz, created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 row_version integer not null default 1 check(row_version>0), unique(organization_id,project_code), unique(id,organization_id), foreign key(site_id,organization_id)references public.client_sites(id,organization_id)on delete restrict,
 check(target_end_on is null or started_on is null or target_end_on>=started_on), check((status='COMPLETED')=(completed_at is not null))
);
create table public.client_project_versions(
 id uuid primary key default extensions.gen_random_uuid(), project_id uuid not null references public.client_projects(id)on delete restrict, organization_id uuid not null,
 version integer not null check(version>0), name_fr text not null check(length(btrim(name_fr))between 2 and 200), name_ar text not null check(length(btrim(name_ar))between 2 and 200),
 description_fr text not null check(length(btrim(description_fr))between 3 and 4000), description_ar text not null check(length(btrim(description_ar))between 3 and 4000),
 objectives jsonb not null default '[]' check(jsonb_typeof(objectives)='array'), scope_snapshot jsonb not null default '{}' check(jsonb_typeof(scope_snapshot)='object'),
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), change_reason text not null check(length(btrim(change_reason))between 3 and 500), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(project_id,version), foreign key(project_id,organization_id)references public.client_projects(id,organization_id)on delete restrict
);
create table public.client_project_tasks(
 id uuid primary key default extensions.gen_random_uuid(), project_id uuid not null references public.client_projects(id)on delete restrict, organization_id uuid not null,
 task_key text not null check(task_key~'^[A-Z][A-Z0-9_-]{1,79}$'), task_type text not null check(task_type in('TASK','MILESTONE')),
 status text not null default 'PENDING' check(status in('PENDING','IN_PROGRESS','BLOCKED','SUBMITTED','ACCEPTED','CANCELLED')),
 due_at timestamptz, assignee_user_id uuid references auth.users(id), current_version integer not null default 1 check(current_version>0), row_version integer not null default 1 check(row_version>0),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 unique(project_id,task_key), unique(id,organization_id), foreign key(project_id,organization_id)references public.client_projects(id,organization_id)on delete restrict
);
create table public.client_project_task_versions(
 id uuid primary key default extensions.gen_random_uuid(), task_id uuid not null references public.client_project_tasks(id)on delete restrict, organization_id uuid not null,
 version integer not null check(version>0), title_fr text not null check(length(btrim(title_fr))between 2 and 240), title_ar text not null check(length(btrim(title_ar))between 2 and 240),
 description_fr text, description_ar text, acceptance_criteria jsonb not null default '[]' check(jsonb_typeof(acceptance_criteria)='array'),
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), change_reason text not null check(length(btrim(change_reason))between 3 and 500), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(task_id,version), foreign key(task_id,organization_id)references public.client_project_tasks(id,organization_id)on delete restrict
);

create table public.client_annual_budgets(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id)on delete restrict, fiscal_year integer not null check(fiscal_year between 2000 and 2200),
 currency char(3) not null check(currency~'^[A-Z]{3}$'), library_id uuid references public.catalog_libraries(id)on delete restrict, site_id uuid, project_id uuid,
 current_version integer not null default 1 check(current_version>0), status text not null default 'DRAFT' check(status in('DRAFT','APPROVED','CLOSED','ARCHIVED')),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(), row_version integer not null default 1 check(row_version>0),
 unique nulls not distinct(organization_id,fiscal_year,currency,library_id,site_id,project_id), unique(id,organization_id),
 foreign key(site_id,organization_id)references public.client_sites(id,organization_id)on delete restrict, foreign key(project_id,organization_id)references public.client_projects(id,organization_id)on delete restrict,
 check(num_nonnulls(library_id,site_id,project_id)>=1)
);
create table public.client_annual_budget_versions(
 id uuid primary key default extensions.gen_random_uuid(), budget_id uuid not null references public.client_annual_budgets(id)on delete restrict, organization_id uuid not null,
 version integer not null check(version>0), amount_minor bigint not null check(amount_minor>=0), approved_amount_minor bigint check(approved_amount_minor is null or approved_amount_minor>=0),
 rationale text not null check(length(btrim(rationale))between 3 and 2000), assumptions jsonb not null default '{}' check(jsonb_typeof(assumptions)='object'),
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(budget_id,version), unique(id,budget_id), foreign key(budget_id,organization_id)references public.client_annual_budgets(id,organization_id)on delete restrict
);

create table public.client_cost_centers(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id)on delete restrict,
 code text not null check(code~'^[A-Z][A-Z0-9_-]{1,39}$'), status text not null default 'ACTIVE' check(status in('ACTIVE','INACTIVE','ARCHIVED')),
 current_version integer not null default 1 check(current_version>0), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(), row_version integer not null default 1 check(row_version>0),
 unique(organization_id,code), unique(id,organization_id)
);
create table public.client_cost_center_versions(
 id uuid primary key default extensions.gen_random_uuid(), cost_center_id uuid not null references public.client_cost_centers(id)on delete restrict, organization_id uuid not null,
 version integer not null check(version>0), name_fr text not null check(length(btrim(name_fr))between 2 and 160), name_ar text not null check(length(btrim(name_ar))between 2 and 160),
 manager_user_id uuid references auth.users(id), allocation_policy_snapshot jsonb not null default '{}' check(jsonb_typeof(allocation_policy_snapshot)='object'), content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),
 change_reason text not null check(length(btrim(change_reason))between 3 and 500), created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(cost_center_id,version), foreign key(cost_center_id,organization_id)references public.client_cost_centers(id,organization_id)on delete restrict
);
create table public.client_cost_allocations(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id)on delete restrict,
 cost_center_id uuid not null, budget_id uuid not null, budget_version_id uuid not null, project_id uuid,
 allocation_type text not null check(allocation_type in('COMMITMENT','ACTUAL','RELEASE')), amount_minor bigint not null check(amount_minor>0), currency char(3) not null check(currency~'^[A-Z]{3}$'),
 reference_type text not null check(reference_type in('PROJECT','CONTRACT','MISSION','INVOICE','MANUAL')), reference_id uuid, evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),
 idempotency_key text not null check(length(idempotency_key)between 8 and 200), correlation_id uuid not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
 unique(organization_id,idempotency_key), foreign key(cost_center_id,organization_id)references public.client_cost_centers(id,organization_id)on delete restrict,
 foreign key(budget_id,organization_id)references public.client_annual_budgets(id,organization_id)on delete restrict, foreign key(budget_version_id,budget_id)references public.client_annual_budget_versions(id,budget_id)on delete restrict,
 foreign key(project_id,organization_id)references public.client_projects(id,organization_id)on delete restrict
);

create table public.client_calendar_events(
 id uuid primary key default extensions.gen_random_uuid(), organization_id uuid not null references public.organizations(id)on delete restrict, project_id uuid,
 event_type text not null check(event_type in('CUSTOM','PROJECT_DEADLINE','APPROVAL','DOCUMENT','INVOICE','MISSION','RFQ')),
 title_fr text not null check(length(btrim(title_fr))between 2 and 240), title_ar text not null check(length(btrim(title_ar))between 2 and 240), starts_at timestamptz not null, ends_at timestamptz,
 status text not null default 'SCHEDULED' check(status in('SCHEDULED','COMPLETED','CANCELLED')), source_type text, source_id uuid,
 created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), row_version integer not null default 1 check(row_version>0),
 foreign key(project_id,organization_id)references public.client_projects(id,organization_id)on delete restrict, check(ends_at is null or ends_at>=starts_at), unique(organization_id,source_type,source_id)
);

create function private.client_portfolio_read(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
 select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_BUYER','CLIENT_ACCOUNTING','CLIENT_MEMBER','CLIENT_VIEWER'],p_actor)
 or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR'],p_actor)
$$;
create function private.client_portfolio_manage(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
 select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_BUYER'],p_actor)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],p_actor)
$$;
create function private.client_budget_manage(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
 select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_ACCOUNTING'],p_actor)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER'],p_actor)
$$;

create function public.create_client_site(p_organization_id uuid,p_code text,p_name_fr text,p_name_ar text,p_address_snapshot jsonb,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;s uuid;begin if a is null or not private.client_portfolio_manage(p_organization_id,a)then raise exception'CLIENT_SITE_CREATE_DENIED'using errcode='42501';end if;
if p_code!~'^[A-Z][A-Z0-9_-]{1,39}$'or length(btrim(coalesce(p_name_fr,'')))not between 2 and 160 or length(btrim(coalesce(p_name_ar,'')))not between 2 and 160 or jsonb_typeof(p_address_snapshot)<>'object'or length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 then raise exception'INVALID_CLIENT_SITE'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'code',p_code,'fr',p_name_fr,'ar',p_name_ar,'address',p_address_snapshot,'reason',p_change_reason));r:=private.begin_contract_command(p_organization_id,'client.site.create',p_idempotency_key,h,a);if r is not null then return r;end if;
insert into public.client_sites(organization_id,code,created_by)values(p_organization_id,p_code,a)returning id into s;insert into public.client_site_versions(site_id,organization_id,version,name_fr,name_ar,address_snapshot,change_reason,content_hash,created_by)values(s,p_organization_id,1,p_name_fr,p_name_ar,p_address_snapshot,p_change_reason,h,a);
r:=jsonb_build_object('outcome','CLIENT_SITE_CREATED','site_id',s,'version',1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','client.site.created','client_site',s::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'client_site',s::text,'ClientSiteCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'client.site.create',p_idempotency_key,r);return r;end$$;

create function public.create_client_project(p_organization_id uuid,p_project_code text,p_site_id uuid,p_name_fr text,p_name_ar text,p_description_fr text,p_description_ar text,p_objectives jsonb,p_scope_snapshot jsonb,p_started_on date,p_target_end_on date,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;p uuid;v uuid;begin if a is null or not private.client_portfolio_manage(p_organization_id,a)then raise exception'CLIENT_PROJECT_CREATE_DENIED'using errcode='42501';end if;
if p_project_code!~'^[A-Z][A-Z0-9_-]{1,39}$'or(p_site_id is not null and not exists(select 1 from public.client_sites where id=p_site_id and organization_id=p_organization_id and status='ACTIVE'))or length(btrim(coalesce(p_name_fr,'')))<2 or length(btrim(coalesce(p_name_ar,'')))<2 or length(btrim(coalesce(p_description_fr,'')))<3 or length(btrim(coalesce(p_description_ar,'')))<3 or jsonb_typeof(p_objectives)<>'array'or jsonb_typeof(p_scope_snapshot)<>'object'or(p_started_on is not null and p_target_end_on<p_started_on)or length(btrim(coalesce(p_change_reason,'')))<3 then raise exception'INVALID_CLIENT_PROJECT'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'code',p_project_code,'site',p_site_id,'fr',p_name_fr,'ar',p_name_ar,'description_fr',p_description_fr,'description_ar',p_description_ar,'objectives',p_objectives,'scope',p_scope_snapshot,'start',p_started_on,'end',p_target_end_on,'reason',p_change_reason));r:=private.begin_contract_command(p_organization_id,'client.project.create',p_idempotency_key,h,a);if r is not null then return r;end if;
insert into public.client_projects(organization_id,project_code,site_id,status,started_on,target_end_on,created_by)values(p_organization_id,p_project_code,p_site_id,case when p_started_on is null then'DRAFT'else'PLANNED'end,p_started_on,p_target_end_on,a)returning id into p;insert into public.client_project_versions(project_id,organization_id,version,name_fr,name_ar,description_fr,description_ar,objectives,scope_snapshot,content_hash,change_reason,created_by)values(p,p_organization_id,1,p_name_fr,p_name_ar,p_description_fr,p_description_ar,p_objectives,p_scope_snapshot,h,p_change_reason,a)returning id into v;
r:=jsonb_build_object('outcome','CLIENT_PROJECT_CREATED','project_id',p,'project_version_id',v,'version',1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','client.project.created','client_project',p::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'client_project',p::text,'ClientProjectCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'client.project.create',p_idempotency_key,r);return r;end$$;

create function public.save_client_project_version(p_project_id uuid,p_expected_row_version integer,p_site_id uuid,p_status text,p_name_fr text,p_name_ar text,p_description_fr text,p_description_ar text,p_objectives jsonb,p_scope_snapshot jsonb,p_started_on date,p_target_end_on date,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.client_projects%rowtype;h text;r jsonb;v uuid;n integer;begin select * into p from public.client_projects where id=p_project_id;if a is null or not found or not private.client_portfolio_manage(p.organization_id,a)then raise exception'CLIENT_PROJECT_SAVE_DENIED'using errcode='42501';end if;
if p.status in('COMPLETED','CANCELLED','ARCHIVED')or p_status not in('DRAFT','PLANNED','ACTIVE','ON_HOLD','COMPLETED','CANCELLED')or(p_site_id is not null and not exists(select 1 from public.client_sites where id=p_site_id and organization_id=p.organization_id and status='ACTIVE'))or length(btrim(coalesce(p_name_fr,'')))<2 or length(btrim(coalesce(p_name_ar,'')))<2 or length(btrim(coalesce(p_description_fr,'')))<3 or length(btrim(coalesce(p_description_ar,'')))<3 or jsonb_typeof(p_objectives)<>'array'or jsonb_typeof(p_scope_snapshot)<>'object'or(p_started_on is not null and p_target_end_on<p_started_on)or length(btrim(coalesce(p_change_reason,'')))<3 then raise exception'INVALID_CLIENT_PROJECT_VERSION'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('project',p.id,'expected',p_expected_row_version,'site',p_site_id,'status',p_status,'fr',p_name_fr,'ar',p_name_ar,'description_fr',p_description_fr,'description_ar',p_description_ar,'objectives',p_objectives,'scope',p_scope_snapshot,'start',p_started_on,'end',p_target_end_on,'reason',p_change_reason));r:=private.begin_contract_command(p.organization_id,'client.project.save.'||p.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;
select * into p from public.client_projects where id=p.id for update;if p.row_version<>p_expected_row_version then raise exception'STALE_CLIENT_PROJECT'using errcode='40001';end if;n:=p.current_version+1;insert into public.client_project_versions(project_id,organization_id,version,name_fr,name_ar,description_fr,description_ar,objectives,scope_snapshot,content_hash,change_reason,created_by)values(p.id,p.organization_id,n,p_name_fr,p_name_ar,p_description_fr,p_description_ar,p_objectives,p_scope_snapshot,h,p_change_reason,a)returning id into v;update public.client_projects set site_id=p_site_id,status=p_status,current_version=n,started_on=p_started_on,target_end_on=p_target_end_on,completed_at=case when p_status='COMPLETED'then clock_timestamp()end,row_version=row_version+1,updated_at=clock_timestamp()where id=p.id;
r:=jsonb_build_object('outcome','CLIENT_PROJECT_VERSION_SAVED','project_id',p.id,'project_version_id',v,'version',n,'row_version',p.row_version+1,'status',p_status);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.organization_id,a,'USER','client.project.version_saved','client_project',p.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.organization_id,'client_project',p.id::text,'ClientProjectVersionSavedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p.organization_id,'client.project.save.'||p.id::text,p_idempotency_key,r);return r;end$$;

create function public.save_client_annual_budget(p_organization_id uuid,p_fiscal_year integer,p_currency char(3),p_library_id uuid,p_site_id uuid,p_project_id uuid,p_amount_minor bigint,p_rationale text,p_assumptions jsonb,p_approve boolean,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;b public.client_annual_budgets%rowtype;v uuid;n integer;begin if a is null or not private.client_budget_manage(p_organization_id,a)then raise exception'CLIENT_BUDGET_SAVE_DENIED'using errcode='42501';end if;
if p_fiscal_year not between 2000 and 2200 or p_currency!~'^[A-Z]{3}$'or num_nonnulls(p_library_id,p_site_id,p_project_id)<1 or p_amount_minor<0 or(p_library_id is not null and not exists(select 1 from public.catalog_libraries where id=p_library_id))or(p_site_id is not null and not exists(select 1 from public.client_sites where id=p_site_id and organization_id=p_organization_id))or(p_project_id is not null and not exists(select 1 from public.client_projects where id=p_project_id and organization_id=p_organization_id))or length(btrim(coalesce(p_rationale,'')))<3 or jsonb_typeof(p_assumptions)<>'object'then raise exception'INVALID_CLIENT_BUDGET'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'year',p_fiscal_year,'currency',p_currency,'library',p_library_id,'site',p_site_id,'project',p_project_id,'amount_minor',p_amount_minor,'rationale',p_rationale,'assumptions',p_assumptions,'approve',p_approve));r:=private.begin_contract_command(p_organization_id,'client.budget.save',p_idempotency_key,h,a);if r is not null then return r;end if;
perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text||':'||p_fiscal_year::text||':'||p_currency||':'||coalesce(p_library_id::text,'')||':'||coalesce(p_site_id::text,'')||':'||coalesce(p_project_id::text,''),0));select * into b from public.client_annual_budgets where organization_id=p_organization_id and fiscal_year=p_fiscal_year and currency=p_currency and library_id is not distinct from p_library_id and site_id is not distinct from p_site_id and project_id is not distinct from p_project_id for update;
