create function public.create_client_cost_center(p_organization_id uuid,p_code text,p_name_fr text,p_name_ar text,p_manager_user_id uuid,p_allocation_policy_snapshot jsonb,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;c uuid;v uuid;begin if a is null or not private.client_budget_manage(p_organization_id,a)then raise exception'CLIENT_COST_CENTER_CREATE_DENIED'using errcode='42501';end if;
if p_code!~'^[A-Z][A-Z0-9_-]{1,39}$'or length(btrim(coalesce(p_name_fr,'')))not between 2 and 160 or length(btrim(coalesce(p_name_ar,'')))not between 2 and 160 or jsonb_typeof(p_allocation_policy_snapshot)<>'object'or length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 or(p_manager_user_id is not null and not private.is_active_org_member(p_organization_id,p_manager_user_id))then raise exception'INVALID_CLIENT_COST_CENTER'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'code',p_code,'fr',p_name_fr,'ar',p_name_ar,'manager',p_manager_user_id,'policy',p_allocation_policy_snapshot,'reason',p_change_reason));r:=private.begin_contract_command(p_organization_id,'client.cost_center.create',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.client_cost_centers(organization_id,code,created_by)values(p_organization_id,p_code,a)returning id into c;insert into public.client_cost_center_versions(cost_center_id,organization_id,version,name_fr,name_ar,manager_user_id,allocation_policy_snapshot,content_hash,change_reason,created_by)values(c,p_organization_id,1,p_name_fr,p_name_ar,p_manager_user_id,p_allocation_policy_snapshot,h,p_change_reason,a)returning id into v;
