create function public.record_client_cost_allocation(p_organization_id uuid,p_cost_center_id uuid,p_budget_id uuid,p_project_id uuid,p_allocation_type text,p_amount_minor bigint,p_reference_type text,p_reference_id uuid,p_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;b public.client_annual_budgets%rowtype;bv public.client_annual_budget_versions%rowtype;allocated bigint;x uuid;begin if a is null or not private.client_budget_manage(p_organization_id,a)then raise exception'CLIENT_COST_ALLOCATION_DENIED'using errcode='42501';end if;
select * into b from public.client_annual_budgets where id=p_budget_id and organization_id=p_organization_id and status='APPROVED'for update;select * into bv from public.client_annual_budget_versions where budget_id=b.id and version=b.current_version;if not found or not exists(select 1 from public.client_cost_centers where id=p_cost_center_id and organization_id=p_organization_id and status='ACTIVE')or(p_project_id is not null and not exists(select 1 from public.client_projects where id=p_project_id and organization_id=p_organization_id))or p_allocation_type not in('COMMITMENT','ACTUAL','RELEASE')or p_amount_minor<=0 or p_reference_type not in('PROJECT','CONTRACT','MISSION','INVOICE','MANUAL')or p_evidence_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_CLIENT_COST_ALLOCATION'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'cost_center',p_cost_center_id,'budget',p_budget_id,'budget_version',bv.id,'project',p_project_id,'type',p_allocation_type,'amount_minor',p_amount_minor,'reference_type',p_reference_type,'reference_id',p_reference_id,'evidence_hash',p_evidence_hash));r:=private.begin_contract_command(p_organization_id,'client.cost.allocate',p_idempotency_key,h,a);if r is not null then return r;end if;
select coalesce(sum(case when allocation_type='RELEASE'then-amount_minor else amount_minor end),0)into allocated from public.client_cost_allocations where budget_id=b.id and budget_version_id=bv.id;if p_allocation_type<>'RELEASE'and allocated+p_amount_minor>bv.approved_amount_minor then raise exception'CLIENT_BUDGET_EXCEEDED'using errcode='23514';elsif p_allocation_type='RELEASE'and p_amount_minor>allocated then raise exception'CLIENT_ALLOCATION_RELEASE_EXCEEDED'using errcode='23514';end if;
insert into public.client_cost_allocations(organization_id,cost_center_id,budget_id,budget_version_id,project_id,allocation_type,amount_minor,currency,reference_type,reference_id,evidence_hash,idempotency_key,correlation_id,created_by)values(p_organization_id,p_cost_center_id,b.id,bv.id,p_project_id,p_allocation_type,p_amount_minor,b.currency,p_reference_type,p_reference_id,p_evidence_hash,p_idempotency_key,p_correlation_id,a)returning id into x;
r:=jsonb_build_object('outcome','CLIENT_COST_ALLOCATED','allocation_id',x,'budget_id',b.id,'budget_version_id',bv.id,'amount_minor',p_amount_minor,'allocation_type',p_allocation_type,'remaining_minor',bv.approved_amount_minor-(allocated+case when p_allocation_type='RELEASE'then-p_amount_minor else p_amount_minor end));insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','client.cost.allocated','client_cost_allocation',x::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'client_cost_allocation',x::text,'ClientCostAllocatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'client.cost.allocate',p_idempotency_key,r);return r;end$$;

create function public.save_client_project_task(p_project_id uuid,p_task_key text,p_task_type text,p_status text,p_due_at timestamptz,p_assignee_user_id uuid,p_title_fr text,p_title_ar text,p_description_fr text,p_description_ar text,p_acceptance_criteria jsonb,p_change_reason text,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.client_projects%rowtype;t public.client_project_tasks%rowtype;h text;r jsonb;task_version integer;progress integer;v uuid;begin select * into p from public.client_projects where id=p_project_id;if a is null or not found or not private.client_portfolio_manage(p.organization_id,a)then raise exception'CLIENT_PROJECT_TASK_DENIED'using errcode='42501';end if;
if p_task_key!~'^[A-Z][A-Z0-9_-]{1,79}$'or p_task_type not in('TASK','MILESTONE')or p_status not in('PENDING','IN_PROGRESS','BLOCKED','SUBMITTED','ACCEPTED','CANCELLED')or length(btrim(coalesce(p_title_fr,'')))<2 or length(btrim(coalesce(p_title_ar,'')))<2 or jsonb_typeof(p_acceptance_criteria)<>'array'or length(btrim(coalesce(p_change_reason,'')))<3 then raise exception'INVALID_CLIENT_PROJECT_TASK'using errcode='22023';end if;
h:=private.canonical_request_hash(jsonb_build_object('project',p.id,'key',p_task_key,'type',p_task_type,'status',p_status,'due',p_due_at,'assignee',p_assignee_user_id,'fr',p_title_fr,'ar',p_title_ar,'description_fr',p_description_fr,'description_ar',p_description_ar,'criteria',p_acceptance_criteria,'reason',p_change_reason,'expected',p_expected_row_version));r:=private.begin_contract_command(p.organization_id,'client.project.task.save.'||p.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;
select * into t from public.client_project_tasks where project_id=p.id and task_key=p_task_key for update;if found then if t.row_version<>p_expected_row_version then raise exception'STALE_CLIENT_PROJECT_TASK'using errcode='40001';end if;task_version:=t.current_version+1;update public.client_project_tasks set status=p_status,due_at=p_due_at,assignee_user_id=p_assignee_user_id,current_version=task_version,row_version=row_version+1,updated_at=clock_timestamp()where id=t.id;else if p_expected_row_version<>0 then raise exception'STALE_CLIENT_PROJECT_TASK'using errcode='40001';end if;task_version:=1;insert into public.client_project_tasks(project_id,organization_id,task_key,task_type,status,due_at,assignee_user_id,created_by)values(p.id,p.organization_id,p_task_key,p_task_type,p_status,p_due_at,p_assignee_user_id,a)returning * into t;end if;
insert into public.client_project_task_versions(task_id,organization_id,version,title_fr,title_ar,description_fr,description_ar,acceptance_criteria,content_hash,change_reason,created_by)values(t.id,p.organization_id,task_version,p_title_fr,p_title_ar,p_description_fr,p_description_ar,p_acceptance_criteria,h,p_change_reason,a)returning id into v;
select coalesce((count(*)filter(where status='ACCEPTED')*10000/nullif(count(*),0))::integer,0)into progress from public.client_project_tasks where project_id=p.id and status<>'CANCELLED';update public.client_projects set progress_basis_points=progress,updated_at=clock_timestamp(),row_version=row_version+1 where id=p.id;
r:=jsonb_build_object('outcome','CLIENT_PROJECT_TASK_SAVED','task_id',t.id,'task_version_id',v,'task_version',task_version,'project_progress_basis_points',progress);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.organization_id,a,'USER','client.project_task.saved','client_project_task',t.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.organization_id,'client_project',p.id::text,'ClientProjectTaskSavedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p.organization_id,'client.project.task.save.'||p.id::text,p_idempotency_key,r);return r;end$$;

create function public.schedule_client_calendar_event(p_organization_id uuid,p_project_id uuid,p_event_type text,p_title_fr text,p_title_ar text,p_starts_at timestamptz,p_ends_at timestamptz,p_source_type text,p_source_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;e uuid;begin if a is null or not private.client_portfolio_manage(p_organization_id,a)then raise exception'CLIENT_CALENDAR_SCHEDULE_DENIED'using errcode='42501';end if;if(p_project_id is not null and not exists(select 1 from public.client_projects where id=p_project_id and organization_id=p_organization_id))or p_event_type not in('CUSTOM','PROJECT_DEADLINE','APPROVAL','DOCUMENT','INVOICE','MISSION','RFQ')or length(btrim(coalesce(p_title_fr,'')))<2 or length(btrim(coalesce(p_title_ar,'')))<2 or p_starts_at is null or(p_ends_at is not null and p_ends_at<p_starts_at)or((p_source_type is null)<>(p_source_id is null))then raise exception'INVALID_CLIENT_CALENDAR_EVENT'using errcode='22023';end if;
