r:=jsonb_build_object('outcome','CLIENT_CALENDAR_EVENT_SCHEDULED','calendar_event_id',e);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','client.calendar_event.scheduled','client_calendar_event',e::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'client_calendar_event',e::text,'ClientCalendarEventScheduledV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'client.calendar.schedule',p_idempotency_key,r);return r;end$$;

create view public.client_central_calendar with(security_invoker=true)as
 select e.organization_id,e.project_id,e.id as item_id,'CLIENT_EVENT'::text as source_kind,e.event_type,e.title_fr,e.title_ar,e.starts_at,e.ends_at,e.status from public.client_calendar_events e
 union all select t.organization_id,t.project_id,t.id,'PROJECT_TASK',t.task_type,v.title_fr,v.title_ar,t.due_at,null::timestamptz,t.status from public.client_project_tasks t join public.client_project_task_versions v on v.task_id=t.id and v.version=t.current_version where t.due_at is not null
 union all select m.client_organization_id,null::uuid,ms.id,'MISSION_MILESTONE','MISSION',ms.title_fr,ms.title_ar,ms.due_at,null::timestamptz,ms.status from public.mission_milestones ms join public.missions m on m.id=ms.mission_id where ms.due_at is not null;

